const r = await tools.exec_command({cmd:"python - <<'PY'
from pathlib import Path
import json
p=Path('logs/host_memory.jsonl')
rows=[json.loads(x) for x in p.read_text().splitlines()]
print(len(rows))
for i in [0,1,2,10,50,100,200,300,400,500,600,700,800,900,947]:
 if i>=len(rows): continue
 x=rows[i]; c=x['cgroup']; print(i, x['time'], 'current',int(c.get('memory.current',0))/2**30,'peak',int(c.get('memory.peak',0))/2**30,'events',c.get('memory.events'))
# maxima and timestamps
for key in ['memory.current','memory.peak']:
 vals=[int(x['cgroup'][key]) for x in rows if key in x['cgroup']]
 m=max(vals); print(key,m/2**30, 'at',[(i,rows[i]['time']) for i,x in enumerate(rows) if int(x['cgroup'].get(key,0))==m][:3])
# process max per pid/name
mx={}
for x in rows:
 for q in x['processes']:
  k=(q['pid'],q['name']); mx[k]=max(mx.get(k,0),q['rss'])
print('proc maxima')
for k,v in sorted(mx.items(),key=lambda kv:kv[1],reverse=True)[:20]: print(k,v/2**30)
